package asignacion
import("fmt";"sort";"transporte/Internal/errores";"transporte/Internal/grafo";"transporte/Internal/modelos")
func AsignarSolicitudes(g *grafo.Grafo,s []modelos.Solicitud,v []modelos.Vehiculo)([]modelos.Asignacion,[]modelos.Solicitud){free:=map[string]modelos.Vehiculo{};for _,x:=range v{if x.Disponible{free[x.ID]=x}};in:=append([]modelos.Solicitud(nil),s...);sort.SliceStable(in,func(i,j int)bool{if in[i].Prioridad==in[j].Prioridad{return in[i].ID<in[j].ID};return in[i].Prioridad>in[j].Prioridad});a:=[]modelos.Asignacion{};p:=[]modelos.Solicitud{};for _,x:=range in{found:=false;best:=0.0;var bv modelos.Vehiculo;var br modelos.Ruta;for _,z:=range free{if z.Capacidad<x.Peso{continue};pick,e:=g.RutaMinima(z.Origen,x.Origen);if e!=nil{continue};del,e:=g.RutaMinima(x.Origen,x.Destino);if e!=nil{continue};c:=pick.Distancia+del.Distancia;if !found||c<best{found=true;best=c;bv=z;br=del}};if found{a=append(a,modelos.Asignacion{Solicitud:x,Vehiculo:bv,Ruta:br});delete(free,bv.ID)}else{p=append(p,x)}};return a,p}
func AsignarSolicitud(g *grafo.Grafo,s modelos.Solicitud,v []modelos.Vehiculo)(modelos.Asignacion,error){a,p:=AsignarSolicitudes(g,[]modelos.Solicitud{s},v);if len(p)>0{return modelos.Asignacion{},&errores.CapacidadInsuficienteError{Mensaje:fmt.Sprintf("No se pudo asignar %s",s.ID)}};return a[0],nil}